(41861, 'Job 30:20', 'Job', 30, 20, 'زۀ تا ته فرياد کوم او تۀ زما فرياد نۀ اورې، زۀ ستا په وړاندې ودرېږم خو تۀ ما ته ګورې قدرې هم نه.', 'زۀ تا ته فریاد کوم او تۀ زما فریاد نۀ اورې، زۀ ستا په وراندې ودرېزم خو تۀ ما ته ګورې قدرې هم نه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_30_20.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(41862, 'Job 30:21', 'Job', 30, 21, 'تا ما سره زياتے شروع کړے دے، او د خپل طاقت سره ما له تکليف راکوې.', 'تا ما سره زیاتے شروع کرے دے، او د خپل طاقت سره ما له تکلیف راکوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_30_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41863, 'Job 30:22', 'Job', 30, 22, 'تا زۀ په هوا باندې اوچت کړے يم، او په طوفان کښې دې تباه کړے يم.', 'تا زۀ په هوا باندې اوچت کرے یم، او په طوفان کشې دې تباه کرے یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_30_22.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(41864, 'Job 30:23', 'Job', 30, 23, 'ما ته پته ده چې تۀ به ما مرګ له بوځې، هغه کور ته کوم چې د ټولو ژوندو دپاره تيار شوے دے.', 'ما ته پته ده چې تۀ به ما مرګ له بوجې، هغه کور ته کوم چې د تولو ژوندو دپاره تیار شوے دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_30_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41865, 'Job 30:24', 'Job', 30, 24, 'څوک د ضرورتمندو خِلاف کار نۀ کوى، کله چې په يو مصيبت کښې هغوئ د مدد دپاره چغې وهى.', 'چوک د ضرورتمندو خلاف کار نۀ کوی، کله چې په یو مصیبت کشې هغوی د مدد دپاره چغې وهی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_30_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41866, 'Job 30:25', 'Job', 30, 25, 'څوک چې په تکليف کښې وُو ولې ما د هغوئ دپاره ژړا ونۀ کړه څۀ؟ او زما زړۀ په غريبانانو باندې خفه نۀ وو څۀ؟', 'چوک چې په تکلیف کشې وو ولې ما د هغوی دپاره ژرا ونۀ کره چۀ؟ او زما زرۀ په غریبانانو باندې خفه نۀ وو چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_30_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(41867, 'Job 30:26', 'Job', 30, 26, 'خو کله چې ما د ښۀ‌والى لټون وکړو، نو بدوالے راغلو، او کله چې ما د رڼا اِنتظار وکړو، نو تيارۀ راغله.', 'خو کله چې ما د شۀ‌والی لتون وکرو، نو بدوالے راغلو، او کله چې ما د رنا انتظار وکرو، نو تیارۀ راغله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_30_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41868, 'Job 30:27', 'Job', 30, 27, 'زما زړۀ بې‌قراره او په تکليف دے، او سخت وخت په ما باندې راغلے دے.', 'زما زرۀ بې‌قراره او په تکلیف دے، او سخت وخت په ما باندې راغلے دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_30_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41869, 'Job 30:28', 'Job', 30, 28, 'زۀ په داسې تيارۀ کښې ګرځم چې رڼا نۀ وى، زۀ د خلقو په مخکښې ودرېږم او د مدد دپاره چغې وهم.', 'زۀ په داسې تیارۀ کشې ګرجم چې رنا نۀ وی، زۀ د خلقو په مخکشې ودرېزم او د مدد دپاره چغې وهم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_30_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41870, 'Job 30:29', 'Job', 30, 29, 'زۀ د ګيدړانو ورور يم، او د ګونګا ملګرے يم.', 'زۀ د ګیدرانو ورور یم، او د ګونګا ملګرے یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_30_29.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(41871, 'Job 30:30', 'Job', 30, 30, 'زما څرمن توره شى او وغورزيږى، او زما بدن د تبې په وجه سور وى.', 'زما چرمن توره شی او وغورزیزی، او زما بدن د تبې په وجه سور وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_30_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41872, 'Job 30:31', 'Job', 30, 31, 'زما د رباب ساز په ژړا بدل شوے دے، او زما د شپېلۍ آواز د ژړا نه ډک دے.', 'زما د رباب ساز په ژرا بدل شوے دے، او زما د شپېلی اواز د ژرا نه دک دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_30_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41873, 'Isaiah 62:1', 'Isaiah', 62, 1, 'چوپ به نه کښېنم زه د صهیون په خاطر پاتې به نه شم غلی د اورشلیم په خاطر ترڅو ونه ځلیږي عدالت د هغه د سهار د رڼا په شان او ونه ځلیږي ژغورنه یې د څراغ په شان', 'چوپ به نه کشېنم زه د صهیون په خاطر پاتې به نه شم غلی د اورشلیم په خاطر ترچو ونه جلیزی عدالت د هغه د سهار د رنا په شان او ونه جلیزی ژغورنه یې د چراغ په شان', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah062_verse_001.mp3', 'https://drive.google.com/file/d/1yW4q2vzyuAA5Hyg39uQL3WKd17nWzY2R/preview', 1761237841, 1761237841),
(41874, 'Isaiah 62:2', 'Isaiah', 62, 2, 'ای اورشلیمه! وبه ویني عدالت ستا د نړۍ قومونه وبه ګوري ستا شان او شوکت ټول پاچاهان تاته به درکړل شي یو نوی نوم څښتن به کېږدي په تا هغه نوم', 'ای اورشلیمه! وبه وینی عدالت ستا د نری قومونه وبه ګوری ستا شان او شوکت تول پاچاهان تاته به درکرل شی یو نوی نوم چشتن به کېزدی په تا هغه نوم', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah062_verse_002.mp3', 'https://drive.google.com/uc?id=1_76m4CQfGCPpRxZzyCIDTBM1qXfgtjtA&export=download', 1761237841, 1761237841),
